typedef struct {TaxiWorldFrame *f;} Draw;
static int dispatch(void *arg,unsigned kind,size_t payload){Draw *d=arg;TaxiWorldFramePacket *p=d->f->packets+payload;if(kind!=p->kind)return -1;printf(" %u %u %u %u",p->material,p->texture,p->bucket,p->raster_flags);return 0;}
int main(int argc,char **argv){if(argc!=6)return 2;TaxiWorldAsset worlds[2]={{0}};TaxiIndexedAsset indexed[2]={{0}};for(unsigned i=0;i<2;i++)if(taxi_world_asset_load(worlds+i,argv[i+1])||taxi_indexed_asset_load(indexed+i,argv[i+4]))return 3;FILE *file=fopen(argv[3],"rb");unsigned char raw[16388];if(!file||fread(raw,1,sizeof raw,file)!=sizeof raw)return 4;fclose(file);TaxiTrig trig;taxi_trig_decode(&trig,raw+4,raw+8196);unsigned city,n;int cx,cy,cz,yaw,pitch;while(scanf("%u %u %d %d %d %d %d",&city,&n,&cx,&cy,&cz,&yaw,&pitch)==7){if(city>1||n>64||!n)return 5;TaxiWorldAsset w=worlds[city];unsigned char cell[156]={0};cell[0]=(unsigned char)n;for(unsigned i=0;i<n;i++){unsigned ref;if(scanf("%u",&ref)!=1||ref>=w.np)return 6;cell[28+i*2]=(unsigned char)ref;cell[29+i*2]=(unsigned char)(ref>>8);}const unsigned char *cells[1]={cell};w.cells=cells;w.nx=w.nz=1;w.ox=cx;w.oz=cz;w.sx=w.sz=1;uint8_t *seen=calloc(w.np,1),special[1]={0},cache[512]={0};if(!seen)return 7;TaxiRenderPacket storage[64];TaxiRenderQueue q;taxi_render_queue_init(&q,storage,64);TaxiWorldFramePacket packet[64];const int32_t corners[8][4]={{0}};TaxiWorldFrame f={.world=&w,.camera={cx,cy,cz},.yaw=yaw,.pitch=pitch,.trig=&trig,.projection={120,80,192,256,38400},.right=240,.bottom=160,.bounds_corners=corners,.texture_count=indexed[city].count,.textures=indexed+city,.material_cache=cache,.material_cache_size=512,.queue=&q,.packets=packet,.capacity=64,.normal_seen=seen,.normal_seen_size=w.np,.special_seen=special,.special_seen_size=1};if(taxi_world_frame_build(&f))return 8;printf("%u",(unsigned)f.count);Draw d={&f};if(taxi_render_queue_consume(&q,dispatch,&d))return 9;for(unsigned i=0;i<128;i++)if(q.heads[i]!=SIZE_MAX)return 10;if(q.count)return 11;puts("");free(seen);}return 0;}
